// Cruza o perfil de cada cliente com os investimentos do CSV e gera a mensagem
const investimentos = $('Extract from File').all().map(i => i.json);
const corpo = $('Webhook').first().json.body;
const clientes = Array.isArray(corpo) ? corpo : (corpo.clientes || [corpo]);

const templates = {
  Conservador: "foco em renda fixa e segurança",
  Moderado: "um mix equilibrado entre renda fixa e variável",
  Arrojado: "ênfase em ações e maior potencial de retorno"
};

// "R$ 12.500,00" -> 12500
function paraNumero(saldo) {
  if (typeof saldo === "number") return saldo;
  return Number(String(saldo).replace(/[^\d,]/g, "").replace(",", "."));
}

function formatarBRL(valor) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

return clientes.map(c => {
  const perfil = String(c.perfil).trim();
  const saldo = paraNumero(c.saldo);
  const opcoes = investimentos.filter(i => String(i.perfil).trim() === perfil && Number(i.minimo) <= saldo);
  const lista = opcoes.map(o => `${o.produto} (${o.rentabilidade})`).join(", ")
    || "nenhum produto atinge o valor mínimo no momento";
  const mensagem = `Olá, ${c.nome}! Como seu perfil é ${perfil}, recomendamos ${templates[perfil] || "uma conversa com seu assessor"}. Com seu saldo de ${formatarBRL(saldo)}, as opções compatíveis são: ${lista}.`;
  return { json: { nome: c.nome, email: c.email, perfil, saldo, opcoes: opcoes.map(o => o.produto), mensagem } };
});
